questionvariables.text:
/* paramètres du montage d'interférences */
a1: rand([20,30,40,50,60,80,100]);  /* largeur fente en µm */
ua: float(round(a1*rand(100)/100))/10;  /* incertitude en µm fente commerciales +- 10% */
D1: rand([1,1.5,2,2.5,3]);  /* distance écran en m */
uD: 1E-3*(rand(2)+1)/2;  /* incertitude sur D en m */
b1: rand([200,250,300,350,400,450,500]);  /* distance entre les fentes en µm */
ub: float(round(b1*rand(100)/100))/10;  /* incertitude sur b en µm */

/* Sélection aléatoire du laser */
lasers: [[405,"blue"],[520,"green"],[532,"green"],[635,"red"],[650,"red"]];
laser_choisi: rand(lasers);
lambda_1: laser_choisi[1];  /* longueur d'onde en nm */
couleur: laser_choisi[2];  /* couleur du laser */
ui:(rand(10)+3)/10 *1E-3;
i1:float((round(100*lambda_1*1E-9*D1/(b1*1E-6)*1E3))/100)/*interfrange en mm*/
l1:2;
ul1:10;

ta1:[[1,false,"C'est de la réfraction"],[2,false,"C'est de la diffusion"],[3,true,"C'est le phénomène d'interférences"],[4,false,"C'est le phénomène de diffraction"]];
feedback1:[["La réfraction est le changement de direction de propagation d'une onde lorsqu'elle passe d'un milieu transparent à un autre (ex: air à eau). L'expérience décrite se fait dans un seul milieu (l'air) et implique le contournement d'un obstacle ou d'une ouverture, ce qui n'est pas la réfraction."],
["La diffusion est la dispersion de la lumière dans toutes les directions par des particules ou des irrégularités du milieu (ex: diffusion Rayleigh par les molécules de l'atmosphère). Bien que la diffraction soit parfois considérée comme un type de diffusion, le terme exact pour l'étalement de l'onde après passage par une fente est la diffraction. La figure observée (maxima/minima réguliers) est caractéristique de la diffraction."],
["La figure observée est le résultat de la superposition des ondes émises par chaque point de la fente. Les 2 fentes se comportent comme des sources cohérentes et la figure est obtenue par la superposition des ondes provenant des deux sources distinctes (c'est l'expérience des fentes de Young)."],
["La diffraction est le phénomène d'étalement (ou de courbure) des ondes (ici, la lumière laser) lorsqu'elles rencontrent un obstacle ou passent par une seule petite ouverture. La figure obtenue sur l'écran (alternance de franges lumineuses et sombres de même largeur) est la signature classique d'interférences et non diffraction par une fente unique."]];
ta2:i1*mm;
ta3:(D* lambda)/(i);
ta4: b1*1E-6 *m; 
ta5:float((round((100*2*lambda_1*D1/a1)))/100) *mm;
ta6:2*lambda*D/l;
ta7:float((round(100*a1))/100*1E-6) *m;
